typedef unsigned int nslSourceId;
typedef unsigned int nslSoundId;
typedef float nlVector3d[3];

enum nslSoundParamEnum
{
  NSL_SOUNDPARAM_VOLUME
};

#define NSL_INVALID_ID 0

nslSourceId nslLoadSource( const char *soundSourceName );
nslSoundId nslAddSound( nslSourceId soundSource );
void nslSetSoundParam( nslSoundId soundToSet, nslSoundParamEnum whichParam, float newVal );
void nslPlaySound3D( nslSoundId soundToPlay, const nlVector3d &pos );

class os_developer_options
{
  virtual ~os_developer_options();
  bool flags[18];
  static os_developer_options *instance;
public:
  enum flags_t
  {
    FLAG_NO_AUDIO = 17
  };
  static inline os_developer_options *inst() { return instance; }
  bool is_flagged( flags_t flag ) const { return flags[flag]; }
};

class SFXEngine
{
  char released_layout[4468];
  bool paused;
public:
  void paddle( bool left, float x, float y, float z, float volume );
};

void SFXEngine::paddle( bool left, float x, float y, float z, float volume )
  {
  if(os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
    return;
  if (paused) return;
  if ( left )
  {
    nslSourceId src = nslLoadSource( "MOVEMENT_PADDLE1" );
    if ( src != NSL_INVALID_ID )
    {
      nslSoundId snd = nslAddSound( src );
      if ( snd != NSL_INVALID_ID )
      {
        nlVector3d pos;
        pos[0] = x;
        pos[1] = y;
        pos[2] = z;
        nslSetSoundParam( snd, NSL_SOUNDPARAM_VOLUME, volume );
        nslPlaySound3D( snd, pos );

      }
    }
  }
  else
  {
    nslSourceId src = nslLoadSource( "MOVEMENT_PADDLE2" );
    if ( src != NSL_INVALID_ID )
    {
      nslSoundId snd = nslAddSound( src );
      if ( snd != NSL_INVALID_ID )
      {
        nlVector3d pos;
        pos[0] = x;
        pos[1] = y;
        pos[2] = z;
        nslSetSoundParam( snd, NSL_SOUNDPARAM_VOLUME, volume );
        nslPlaySound3D( snd, pos );

      }
    }
  }



}
